index 0000000..0000000 100644
--- a/app/src/queue.test.js
+++ b/app/src/queue.test.js
@@ -1,29 +1,29 @@
 import Bull from 'bull'
 import createQueue from './queue'

 jest.mock('bull')

 beforeEach(() => {
   Bull.mockClear()
 })

 describe('queue', () => {
   it(`creates a queue with default options`, () => {
     const queueMock = { add: () => {}, process: () => {} }
     Bull.mockResolvedValue(queueMock)

     expect(createQueue('redis://redis:6379')).resolves.toBe(queueMock) // eslint-disable-line jest/valid-expect
     expect(Bull).toHaveBeenCalledTimes(1)
     expect(Bull).toHaveBeenCalledWith('request-queue', 'redis://redis:6379', {})
   })

   it(`creates a queue with specified options`, () => {
     const queueMock = { add: () => {}, process: () => {} }
     Bull.mockResolvedValue(queueMock)

     expect(createQueue('redis://redis:6379', { myOption: 'myOptionValue' })).resolves.toBe(queueMock) // eslint-disable-line jest/valid-expect
     expect(Bull).toHaveBeenCalledTimes(1)
     expect(Bull).toHaveBeenCalledWith('request-queue', 'redis://redis:6379', { myOption: 'myOptionValue' })
   })
 })

diff --git a/app/src/manager/queue/jobCompletedHandler.js b/app/src/manager/queue/jobCompletedHandler.js
index 0000000..0000000 100644
--- a/app/src/manager/queue/jobCompletedHandler.js
+++ b/app/src/manager/queue/jobCompletedHandler.js
@@ -1,18 +1,18 @@
 import { juxt, when } from 'ramda'
 import { resolveJobDuration } from './utils'

 // jobCompletedHandler :: (Logger, Queue, RequestRegistry) -> Function
 export default (logger, queue, requestRegistry) => (jobId, result) => when(
   jobId => requestRegistry.has(jobId),
   juxt([
     jobId => requestRegistry.complete(jobId, JSON.parse(result)),
     async jobId => {
       const job = await queue.getJob(jobId)

       logger.info(`${jobId} ${job.data.url} 200 ${resolveJobDuration(job)}`)

       job.remove()
     },
   ]),
 )(jobId)

diff --git a/app/src/manager/queue/jobFailedHandler.js b/app/src/manager/queue/jobFailedHandler.js
index 0000000..0000000 100644
--- a/app/src/manager/queue/jobFailedHandler.js
+++ b/app/src/manager/queue/jobFailedHandler.js
@@ -1,28 +1,28 @@
 import { T, always, cond, juxt, test, when } from 'ramda'
 import { resolveJobDuration } from './utils'

 // resolveStatusCodeFromError :: String -> Integer
 const resolveStatusCodeFromError = cond([
   [error => test(/timeout/i, error), always(504)],
   [error => test(/timed out/i, error), always(504)],
   [T, always(500)],
 ])

 // jobFailedHandler :: (Logger, Queue, RequestRegistry) -> Function
 export default (logger, queue, requestRegistry) => (jobId, error) => when(
   jobId => requestRegistry.has(jobId),
   juxt([
     jobId => requestRegistry.fail(
       jobId,
       resolveStatusCodeFromError(error),
     ),
     async jobId => {
       const job = await queue.getJob(jobId)

       logger.error(`${jobId} ${job.data.url} ${resolveStatusCodeFromError(error)} ${resolveJobDuration(job)} ${error}`)

       job.remove()
     },
   ]),
 )(jobId)

diff --git a/app/src/worker/initWorker.js b/app/src/worker/initWorker.js
index 0000000..0000000 100644
--- a/app/src/worker/initWorker.js
+++ b/app/src/worker/initWorker.js
@@ -1,20 +1,20 @@
 import { call, pipe, tap } from 'ramda'
 import createScriptProvider from './scriptProvider'
 import queueProcessHandler from './queue/processHandler'

 // initWorker :: (Configuration, Logger, Queue) -> Function
 export default (configuration, logger, queue) => call(pipe(
   tap(() => logger.debug('Initializing worker.')),
   tap(pipe(
     () => createScriptProvider(),
     scriptProvider => queue.process(1, queueProcessHandler(configuration, logger, scriptProvider)),
   )),
   tap(() => logger.debug('Worker initialized.')),
   // Returns a function to be used to gracefully shutdown the worker
   () => async () => {
     logger.debug('Gracefully shutting down worker')

     await queue.close()
   },
 ))

